class A:
    def greet(self):
        print('A.greet')
        super().greet() if hasattr(super(), 'greet') else None

class B(A):
    def greet(self):
        print('B.greet')
        super().greet()

class C(A):
    def greet(self):
        print('C.greet')
        super().greet()

class D(B, C):
    def greet(self):
        print('D.greet')
        super().greet()

d = D()
d.greet()
# D.greet
# B.greet
# C.greet
# A.greet

print(D.__mro__)
# (<class 'D'>, <class 'B'>, <class 'C'>, <class 'A'>, <class 'object'>)

# Mixin pattern — cooperative __init__
class TimestampMixin:
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)   # passes args along the chain
        from datetime import datetime
        self.created_at = datetime.now()

class LogMixin:
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._log = []

class Service(LogMixin, TimestampMixin):
    def __init__(self, name: str):
        super().__init__()  # triggers the whole chain
        self.name = name

print(Service.__mro__)
# Service → LogMixin → TimestampMixin → object
